        for (I = 0; I <= f_Buttons.LastIndex; I++)
        {
            if (f_Buttons.Variants[I] == anActionID)
            {
                result = I;
                break;
            }
        }
        return result;
    }
    
    public bool DoAction(in IFURQActionData anActionData)
    {
        bool result;
        result = false;
        if (anActionData != null)
        {
            if (anActionData.LabelIdx > ( - 1))
            {
                if (anActionData.Modifier == amNone)
                {
                    result = DoActionFinal(anActionData);
                }
                else
                {
                    if (State == csPause)
                    {
                        ExecuteProc(anActionData.LabelIdx);
                    }
                    else
                    {
                        JumpToLabelIdx(anActionData.LabelIdx);
                    }
                    result = true;
                }
            }
        }
        return result;
    }
    
