    protected virtual bool DoActionFinal(in IFURQActionData anActionData)
    {
        string l_CommonStr;
        int l_Idx;
        bool result;
    
        result = false;
        try
        {
            IncLocationCount(anActionData.LabelIdx);
            JumpToLabelIdx(anActionData.LabelIdx);
            Variables[cVarPreviousLoc] = Variables[cVarCurrentLoc];
            Variables[cVarCurrentLoc] = Code.Labels[anActionData.LabelIdx];
            if (Variables[cVarCommon] != 0)
            {
                l_CommonStr = (cLocCommonPrefix + FormatNumber(global::furqTypesModule.EnsureReal(Variables[cVarCommon])));
            }
            else
            {
                l_CommonStr = cLocCommon;
            }
            l_Idx = Code.Labels.IndexOf(l_CommonStr);
            if (l_Idx != ( - 1))
            {
                ExecuteProc(l_Idx);
            }
            result = true;
        }
        finally
        {
            ClearButtons();
            f_Actions.Clear();
            f_MenuActions.Clear();
            f_Menu.Clear();
        }
        return result;
    }
    
    protected virtual void DoLoadData(TFURQFiler aFiler)
    {
        int l_Num;
        int I;
        string l_Name;
        Variant l_Value;
    
        l_Num = aFiler.ReadInteger;
        for (I = 1; I <= l_Num; I++)
        {
            l_Name = aFiler.ReadString;
            l_Value = aFiler.ReadVarValue;
            Variables[l_Name] = l_Value;
        }
        l_Num = aFiler.ReadInteger;
        for (I = 1; I <= l_Num; I++)
        {
            l_Name = aFiler.ReadString;
            l_Value = aFiler.ReadDouble;
            AddToInventory(l_Name, l_Value);
        }
        f_Stack.Load(aFiler);
        LoadActions(aFiler);
        LoadButtons(aFiler);
    }
    
    protected virtual void DoSaveData(TFURQFiler aFiler)
    {
        int I;
    
        aFiler.WriteInteger(f_Variables.Count);
        for (I = 0; I <= f_Variables.LastIndex; I++)
        {
            aFiler.WriteString(f_Variables[I]);
            aFiler.WriteVarValue(f_Variables.Variants[I]);
        }
        aFiler.WriteInteger(f_Inventory.Count);
        for (I = 0; I <= f_Inventory.LastIndex; I++)
        {
            aFiler.WriteString(f_Inventory[I]);
            aFiler.WriteDouble(f_Inventory.Variants[I]);
        }
        f_Stack.Save(aFiler);
        SaveActions(aFiler);
        SaveButtons(aFiler);
    }
    
