    public void LoadFromStream(TStream aStream, bool aIgnoreHash)
    {
        TFURQFiler l_R;
        string l_Signature;
        string l_Location;
        int I;
        TMD5Digest l_Hash = default!;
    
        l_R = TFURQFiler.Create(aStream);
        try
        {
            l_Signature = l_R.ReadString;
            if (l_Signature != cSaveFileSignature)
            {
                throw new EFURQRunTimeError(sCorruptedSaveFile);
            }
            l_R.ReadString();
            l_R.ReadDouble();
            l_R.Stream.ReadBuffer(l_Hash, SizeOf(TMD5Digest));
            if (!aIgnoreHash & ~MD5DigestCompare(l_Hash, f_Code.SourceHash))
            {
                throw new EFURQRunTimeError(sBadVersionSaveFile);
            }
            Restart();
            l_Location = l_R.ReadString;
            DoLoadData(l_R);
        }
        finally
        {
            global::FireURQ.Runtime.TObject.Free(l_R);
        }
        if (l_Location != "")
        {
            ForgetProcs();
            ClearText();
            ClearButtons();
            f_Actions.Clear();
            I = f_Code.Labels.IndexOf(l_Location);
            if (I == ( - 1))
            {
                JumpToLine(0);
            }
            else
            {
                JumpToLabelIdx(I);
            }
        }
    }
    
