    public virtual bool SystemProc(string aProcName, IJclStringList aParams)
    {
        string l_Prec;
        long l_Int;
        int l_Len;
        int l_Pos;
        double l_Power;
        bool result;
    
        result = false;
        if (AnsiSameText(aProcName, c_s_sin) & (aParams.Count > 0))
        {
            Variables[c_s_result] = Sin(aParams.Variants[0]);
            result = true;
        }
        else
        {
            if (AnsiSameText(aProcName, c_s_cos) & (aParams.Count > 0))
            {
                Variables[c_s_result] = Cos(aParams.Variants[0]);
                result = true;
            }
            else
            {
                if (AnsiSameText(aProcName, c_s_tan) & (aParams.Count > 0))
                {
                    Variables[c_s_result] = Tan(aParams.Variants[0]);
                    result = true;
                }
                else
                {
                    if (AnsiSameText(aProcName, c_s_arcsin) & (aParams.Count > 0))
                    {
                        Variables[c_s_result] = ArcSin(aParams.Variants[0]);
                        result = true;
                    }
                    else
                    {
                        if (AnsiSameText(aProcName, c_s_arccos) & (aParams.Count > 0))
                        {
                            Variables[c_s_result] = ArcCos(aParams.Variants[0]);
                            result = true;
                        }
                        else
                        {
                            if (AnsiSameText(aProcName, c_s_arctan) & (aParams.Count > 0))
                            {
                                Variables[c_s_result] = ArcTan(aParams.Variants[0]);
                                result = true;
                            }
                            else
                            {
                                if (AnsiSameText(aProcName, c_s_sqrt) & (aParams.Count > 0))
                                {
                                    Variables[c_s_result] = Sqrt(aParams.Variants[0]);
                                    result = true;
                                }
                                else
                                {
                                    if (AnsiSameText(aProcName, c_s_power) & (aParams.Count > 0))
                                    {
                                        if (aParams.Count > 1)
                                        {
                                            l_Power = aParams.Variants[1];
                                        }
                                        else
                                        {
                                            l_Power = 2.0;
                                        }
                                        Variables[c_s_result] = Power(aParams.Variants[0], l_Power);
                                        result = true;
                                    }
                                    else
                                    {
                                        if (AnsiSameText(aProcName, c_s_int) & (aParams.Count > 0))
                                        {
                                            Variables[c_s_result] = Int(aParams.Variants[0]);
                                            result = true;
                                        }
                                        else
                                        {
                                            if (AnsiSameText(aProcName, c_s_tohex) & (aParams.Count > 0))
                                            {
                                                if (aParams.Count > 1)
                                                {
                                                    l_Prec = ("." + IntToStr(aParams.Variants[1]));
                                                }
                                                else
                                                {
                                                    l_Prec = "";
                                                }
                                                l_Int = aParams.Variants[0];
                                                Variables[c_s_result] = Format((("%" + l_Prec) + "x"), new HashSet<int>(new int[] { (int)(l_Int) }));
                                                result = true;
                                            }
                                            else
                                            {
                                                if (AnsiSameText(aProcName, c_s_trim) & (aParams.Count > 0))
                                                {
                                                    Variables[c_s_result] = Trim(EnsureString(aParams.Variants[0]));
                                                    result = true;
                                                }
                                                else
                                                {
                                                    if (AnsiSameText(aProcName, c_s_scopy) & (aParams.Count > 1))
                                                    {
                                                        if (aParams.Count > 2)
                                                        {
                                                            l_Len = aParams.Variants[2];
                                                        }
                                                        else
                                                        {
                                                            l_Len = MaxInt;
                                                        }
                                                        l_Pos = aParams.Variants[1];
                                                        Variables[c_s_result] = Copy(EnsureString(aParams.Variants[0]), l_Pos, l_Len);
                                                        result = true;
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        return result;
    }
    
